  Object.values(fc).filter((w) => w.type === 'wall' && w.level >= 2).forEach((w) => slots.push({ i: (w.i1 + w.i2) / 2, j: (w.j1 + w.j2) / 2, elev: wallHeightFor(w.level) + 2 }));
