function ordinalForNewMonarch(name, ancestors) {
  return ancestors.filter((a) => a.name === name).length + 1;
}
// The older the king, the likelier a given year is his last — rolled once each birthday.
// Flat (and generous) through prime adulthood, then climbs steeply into a medieval-plausible
// old-age mortality curve.
function ageDeathChancePerYear(age) {
  if (age < 40) return 0;
  if (age < 50) return 0.01;
  if (age < 60) return 0.03;
  if (age < 70) return 0.06;
  if (age < 80) return 0.12;
  return 0.22;
}
// "Gesundheit" (health, 0-100): a separate stat from age itself, rolled into the death check
// below. It drifts down a little every year just from age (faster once the king is genuinely
// old), takes a real hit from a lost battle or a bout of illness, and can be nudged back up —
// currently only by a lucky Kräuterweib visit, with a Medicus (a permanent court figure) still
// to come as a steadier source of healing.
function healthDeclinePerYear(age) {
  if (age < 40) return 1;
  if (age < 50) return 2;
  if (age < 60) return 3;
  if (age < 70) return 4;
  if (age < 80) return 5;
  return 6;
}
// How much likelier death becomes this year given the king's current health and whether
// he's currently sick — this is what makes "Gesundheit" matter mechanically, not just
// decoratively. Poor health (below 50) scales the base age-related risk up further, and
// active sickness adds a flat extra risk on top ("verkürzt die Lebenszeit").
function healthAdjustedDeathChance(baseChance, health, sick) {
  const healthPenalty = health < 50 ? (50 - health) / 100 : 0; // up to +50% at 0 health
  const sickPenalty = sick ? 0.06 : 0;
  return Math.min(0.9, baseChance + baseChance * healthPenalty + sickPenalty);
}
// The chance the king falls ill in a given year — checked only while not already sick.
function sicknessChancePerYear(age) {
  if (age < 30) return 0.01;
  if (age < 50) return 0.02;
  if (age < 65) return 0.04;
  return 0.06;
}
