// Which life-stage portrait a family member shows, by age and gender — a reigning or
// once-reigning monarch reads as "King/Queen" (with the older/younger crown variant),
// anyone else just ages through child → young adult → older adult.
function lifeStage(age, gender, isMonarch) {
  if (age < 6) return 'baby';
  if (age < 16) return gender === 'f' ? 'girl' : 'boy';
  // From 16 on, everyone reads as "young royal" regardless of whether they actually hold the
  // throne — a prince or princess of 16 is drawn the same as a young king/queen, not still as
  // a child. Only the older-age tiers keep the crowned-vs-not distinction.
  if (age < 30) return gender === 'f' ? 'youngQueen' : 'youngKing';
  if (age < 50) return gender === 'f' ? (isMonarch ? 'queen' : 'youngQueen') : (isMonarch ? 'king' : 'youngKing');
  return gender === 'f' ? (isMonarch ? 'oldQueen' : 'queen') : (isMonarch ? 'oldKing' : 'king');
}
