// The Maurische Kämpfer's combat lessons: +25% damage for foot soldiers (soldiers and
// archers) — not the mounted champions, who fight in an entirely different style.
const MOORISH_COMBAT_BONUS = 1.25;
// The Armbrustmacher's upgrades: crossbows for the defending archers, permanently — the
// second (pricier) visit refines them further, stacking on top of the first.
const CROSSBOW_DAMAGE_MULT = 1.3;
const CROSSBOW_DAMAGE_MULT_2 = 1.15;
const ARCHER_RANGE = 4.6;
const ARCHER_HEIGHT_RANGE_DIVISOR = 40; // every 40 elevation units of height adds +1 range
// Archers posted up on a tower or the keep aren't just shooting further — they're also
// genuinely harder to hit back: a smaller silhouette against the sky, partial cover from the
// battlements. Caps out at a 50% reduction so elevation helps a lot without making them
// completely safe.
function elevationDefenseMult(elev) {
  if (!elev || elev <= 0) return 1;
  return Math.max(0.35, 1 - elev / 65);
}
// Any attacker type that fights at range with a bow, regardless of which faction sent them.
// (The king's own archers count here too when they are the ones storming a castle.)
const ATTACKER_ARCHER_TYPES = new Set(['saxonArcher', 'robinArcher', 'archer']);
// Units that fight hand-to-hand — these are the ones subject to the per-target crowding cap
// below, since "ganging up" only really means anything when swords are involved; archers and
// catapults shooting the same target from range don't physically crowd anyone out.
function isMeleeUnit(u) {
  if (u.side === 'attacker') return u.type !== 'saxonCatapult' && !ATTACKER_ARCHER_TYPES.has(u.type);
  return u.type !== 'archer';
}
