  sachsen: { short: 'Angriffe −25 %, Ruf −1/Jahr', from: 'von Sachsen', group: 'north', gift: 'Ein Friedensbund mit dem Feind: jeder Angriff fällt um 25 % schwächer aus — doch manche nennen es Verrat (Ruf −1 jedes Jahr).' },
  aragon: { short: 'Hofstimmung +1,5/Monat, Ruf +1/Jahr', from: 'von Aragon', group: 'south', gift: 'Ein glanzvoller Hof: Stimmung bei Hofe +1,5 jeden Monat, Ruf +1 jedes Jahr.' },
  byzanz: { short: 'Forschung +25 %', from: 'von Byzanz', group: 'south', gift: 'Gelehrte im Gefolge: die Baukunst-Forschung geht ein Viertel schneller.' },
  burgund: { short: '+15 🪙/Monat', from: 'von Burgund', group: 'west', gift: 'Die Erträge ihrer Weinberge: +15 🪙 jeden Monat.' },
  flandern: { short: 'Steuern +15 %', from: 'von Flandern', group: 'west', gift: 'Flämische Kaufleute folgen ihr: die Steuern steigen um 15 %.' },
