  const banner2 = `M ${fx} ${fy} C ${fx + 8} ${fy + 3} ${fx + 14} ${fy - 2} ${fx + 21} ${fy + 2} L ${fx + 16} ${fy + 7} L ${fx + 21} ${fy + 12} C ${fx + 14} ${fy + 8} ${fx + 8} ${fy + 13} ${fx} ${fy + 10} Z`;
