      <Block corners={sq(i, j, ph)} baseElev={parBase} topElev={KEEP_H} topFill={shade(pal.top, -0.22)} faceLeft={shade(pal.left, 0.04)} faceRight={shade(pal.right, 0.04)} texture="stone" seed={seed + 2} shadowHeight={0} />
