    const depth = stage === 'done' || ghost ? DITCH_DEPTH : Math.max(2, DITCH_DEPTH * (stage === 'foundation' ? 0.15 + 0.2 * progress : stage === 'scaffold' ? 0.35 + 0.3 * progress : 0.65 + 0.35 * progress));
